INSERT INTO questions (id, area, subject, prompt, options_json, answer, explanation, key_points_json, version, status) VALUES ('cs-db-index-001', 'CS', '데이터베이스', '데이터베이스 인덱스가 조회에 도움이 되는 경우와 인덱스를 무조건 많이 만들면 안 되는 이유를 말해 주세요.', NULL, NULL, '인덱스는 조건에 맞는 행을 찾을 때 전체 테이블을 읽는 일을 줄일 수 있습니다. 하지만 저장 공간을 쓰고 쓰기 작업마다 인덱스를 갱신해야 하므로 비용이 생깁니다. 실제 조회 조건과 쓰기량을 보고 필요한 인덱스를 선택해야 합니다.', '["조건 조회의 탐색 비용","추가 저장 공간","INSERT·UPDATE·DELETE 유지 비용"]', 1, 'reviewed') ON CONFLICT(id) DO UPDATE SET area=excluded.area, subject=excluded.subject, prompt=excluded.prompt, options_json=excluded.options_json, answer=excluded.answer, explanation=excluded.explanation, key_points_json=excluded.key_points_json, version=excluded.version, status=excluded.status;
INSERT INTO questions (id, area, subject, prompt, options_json, answer, explanation, key_points_json, version, status) VALUES ('cs-db-transaction-001', 'CS', '데이터베이스', '계좌 이체를 여러 SQL 변경으로 처리할 때 트랜잭션이 필요한 이유를 설명해 주세요.', NULL, NULL, '출금과 입금을 하나의 작업 단위로 묶어야 중간 오류로 한쪽 변경만 남는 일을 피할 수 있습니다. 트랜잭션은 성공 시 함께 확정하고 실패 시 미완료 변경을 취소하는 원자성을 제공합니다. 다른 동시 트랜잭션에는 미완성 중간 상태가 보이지 않도록 처리합니다.', '["여러 변경의 한 작업 단위","성공 시 확정·실패 시 취소","미완성 중간 상태의 가시성"]', 1, 'reviewed') ON CONFLICT(id) DO UPDATE SET area=excluded.area, subject=excluded.subject, prompt=excluded.prompt, options_json=excluded.options_json, answer=excluded.answer, explanation=excluded.explanation, key_points_json=excluded.key_points_json, version=excluded.version, status=excluded.status;
INSERT INTO questions (id, area, subject, prompt, options_json, answer, explanation, key_points_json, version, status) VALUES ('cs-http-etag-001', 'CS', '네트워크', '브라우저가 저장한 응답의 ETag를 If-None-Match로 보내면, 서버는 내용이 바뀌지 않았을 때 어떻게 응답할 수 있나요?', NULL, NULL, '서버가 현재 리소스의 ETag와 요청의 If-None-Match 값을 비교합니다. 조건부 GET에서 값이 일치해 리소스가 바뀌지 않았다면, 본문을 다시 보내는 대신 304 Not Modified로 기존 캐시를 사용하도록 알릴 수 있습니다.', '["ETag는 리소스 버전 식별자","If-None-Match 조건 비교","변경 없을 때 조건부 GET의 304 응답"]', 1, 'reviewed') ON CONFLICT(id) DO UPDATE SET area=excluded.area, subject=excluded.subject, prompt=excluded.prompt, options_json=excluded.options_json, answer=excluded.answer, explanation=excluded.explanation, key_points_json=excluded.key_points_json, version=excluded.version, status=excluded.status;
INSERT INTO questions (id, area, subject, prompt, options_json, answer, explanation, key_points_json, version, status) VALUES ('cs-http-idempotent-001', 'CS', '네트워크', 'HTTP에서 멱등성을 어떻게 설명하나요? GET과 PUT을 예로 들어 주세요.', NULL, NULL, '같은 요청을 여러 번 보냈을 때 서버에 의도한 효과가 한 번 보낸 경우와 같으면 그 메서드는 멱등적입니다. GET은 조회를 의도하는 안전한 메서드라 멱등적이고, PUT은 같은 표현으로 전체 대체하는 요청을 반복해도 의도한 최종 상태가 같습니다. 응답 코드까지 매번 같아야 한다는 뜻은 아닙니다.', '["반복 요청의 의도한 효과","GET과 PUT의 예","응답 동일성이나 부작용 없음과 구별"]', 1, 'reviewed') ON CONFLICT(id) DO UPDATE SET area=excluded.area, subject=excluded.subject, prompt=excluded.prompt, options_json=excluded.options_json, answer=excluded.answer, explanation=excluded.explanation, key_points_json=excluded.key_points_json, version=excluded.version, status=excluded.status;
INSERT INTO questions (id, area, subject, prompt, options_json, answer, explanation, key_points_json, version, status) VALUES ('cs-java-hashmap-001', 'CS', '자료구조', 'Java HashMap의 조회가 보통 빠른 이유와, 그 성능 설명에 붙는 전제를 말해 주세요.', NULL, NULL, 'HashMap은 키의 해시값으로 버킷을 찾아 값을 조회합니다. 해시 함수가 키를 버킷에 적절히 분산한다는 전제에서 get과 put 같은 기본 연산은 보통 상수 시간 성능을 냅니다. 충돌이 많거나 크기 조정이 필요한 상황까지 항상 같은 시간이 보장되는 것은 아닙니다.', '["키 해시값과 버킷","분산이 좋을 때의 기본 연산 성능","충돌과 크기 조정이라는 예외"]', 1, 'reviewed') ON CONFLICT(id) DO UPDATE SET area=excluded.area, subject=excluded.subject, prompt=excluded.prompt, options_json=excluded.options_json, answer=excluded.answer, explanation=excluded.explanation, key_points_json=excluded.key_points_json, version=excluded.version, status=excluded.status;
INSERT INTO questions (id, area, subject, prompt, options_json, answer, explanation, key_points_json, version, status) VALUES ('cs-os-threads-001', 'CS', '운영체제', '같은 프로세스에 속한 두 스레드는 어떤 자원을 공유하고, 각 스레드에 따로 있는 것은 무엇인가요?', NULL, NULL, '같은 프로세스의 스레드는 코드와 전역 데이터·힙 같은 주소 공간을 공유합니다. 각 스레드에는 별도의 스택과 실행 상태가 있습니다. 공유 데이터에 동시에 접근할 때는 동기화가 필요할 수 있습니다.', '["주소 공간과 전역 데이터 공유","스레드별 스택과 실행 상태","공유 데이터 접근의 동기화"]', 1, 'reviewed') ON CONFLICT(id) DO UPDATE SET area=excluded.area, subject=excluded.subject, prompt=excluded.prompt, options_json=excluded.options_json, answer=excluded.answer, explanation=excluded.explanation, key_points_json=excluded.key_points_json, version=excluded.version, status=excluded.status;
INSERT INTO questions (id, area, subject, prompt, options_json, answer, explanation, key_points_json, version, status) VALUES ('ct-average-001', 'CT', '기초 수리 예제', '다섯 수의 평균이 17입니다. 네 수가 12, 15, 18, 19일 때 남은 한 수는 무엇인가요?', '["19","20","21","22"]', 3, '다섯 수의 합은 17×5=85이고, 주어진 네 수의 합은 64입니다. 남은 수는 85−64=21입니다.', '[]', 1, 'reviewed') ON CONFLICT(id) DO UPDATE SET area=excluded.area, subject=excluded.subject, prompt=excluded.prompt, options_json=excluded.options_json, answer=excluded.answer, explanation=excluded.explanation, key_points_json=excluded.key_points_json, version=excluded.version, status=excluded.status;
INSERT INTO questions (id, area, subject, prompt, options_json, answer, explanation, key_points_json, version, status) VALUES ('ct-compound-change-001', 'CT', '기초 수리 예제', '어떤 수가 800에서 15% 증가한 다음, 증가한 값에서 10% 감소했습니다. 최종 값은 무엇인가요?', '["800","810","828","840"]', 3, '800×1.15=920이고, 920×0.9=828입니다. 증가율과 감소율을 바로 상쇄할 수는 없습니다.', '[]', 1, 'reviewed') ON CONFLICT(id) DO UPDATE SET area=excluded.area, subject=excluded.subject, prompt=excluded.prompt, options_json=excluded.options_json, answer=excluded.answer, explanation=excluded.explanation, key_points_json=excluded.key_points_json, version=excluded.version, status=excluded.status;
INSERT INTO questions (id, area, subject, prompt, options_json, answer, explanation, key_points_json, version, status) VALUES ('ct-discount-001', 'CT', '기초 수리 예제', '정가가 24,000원인 상품을 25% 할인하면 판매 가격은 얼마인가요?', '["16,000원","18,000원","19,000원","20,000원"]', 2, '할인액은 24,000×0.25=6,000원입니다. 판매 가격은 24,000−6,000=18,000원입니다.', '[]', 1, 'reviewed') ON CONFLICT(id) DO UPDATE SET area=excluded.area, subject=excluded.subject, prompt=excluded.prompt, options_json=excluded.options_json, answer=excluded.answer, explanation=excluded.explanation, key_points_json=excluded.key_points_json, version=excluded.version, status=excluded.status;
INSERT INTO questions (id, area, subject, prompt, options_json, answer, explanation, key_points_json, version, status) VALUES ('ct-distance-001', 'CT', '기초 수리 예제', '시속 72km로 일정하게 이동하면 35분 동안 몇 km를 이동하나요?', '["36km","40km","42km","48km"]', 3, '35분은 35/60시간입니다. 거리는 72×35/60=42km입니다.', '[]', 1, 'reviewed') ON CONFLICT(id) DO UPDATE SET area=excluded.area, subject=excluded.subject, prompt=excluded.prompt, options_json=excluded.options_json, answer=excluded.answer, explanation=excluded.explanation, key_points_json=excluded.key_points_json, version=excluded.version, status=excluded.status;
INSERT INTO questions (id, area, subject, prompt, options_json, answer, explanation, key_points_json, version, status) VALUES ('ct-ratio-001', 'CT', '기초 수리 예제', '84개를 A와 B에게 2:5로 나누면 B는 몇 개를 받나요?', '["24개","36개","48개","60개"]', 4, '전체 비율은 2+5=7입니다. B의 몫은 84×5÷7=60개입니다.', '[]', 1, 'reviewed') ON CONFLICT(id) DO UPDATE SET area=excluded.area, subject=excluded.subject, prompt=excluded.prompt, options_json=excluded.options_json, answer=excluded.answer, explanation=excluded.explanation, key_points_json=excluded.key_points_json, version=excluded.version, status=excluded.status;
INSERT INTO questions (id, area, subject, prompt, options_json, answer, explanation, key_points_json, version, status) VALUES ('ct-workrate-001', 'CT', '기초 수리 예제', '같은 일을 혼자 하면 A는 6일, B는 12일 걸립니다. 각자 위의 작업 속도를 유지하며 동시에 일하면 며칠 걸리나요?', '["3일","4일","6일","9일"]', 2, '하루에 A는 전체의 1/6, B는 1/12을 합니다. 합치면 1/4이므로 전체 일에는 4일이 걸립니다.', '[]', 1, 'reviewed') ON CONFLICT(id) DO UPDATE SET area=excluded.area, subject=excluded.subject, prompt=excluded.prompt, options_json=excluded.options_json, answer=excluded.answer, explanation=excluded.explanation, key_points_json=excluded.key_points_json, version=excluded.version, status=excluded.status;
